defmodule JoobQ.TransportOutcomeTest do
  use ExUnit.Case, async: true

  alias JoobQ.{Error, Transport}

  test "a closed connection is a transport error, never a second attempt" do
    closed = %Mint.TransportError{reason: :closed}

    assert {nil, {:error, %Error{reason: :transport, status: nil}}} =
             Transport.outcome({:error, closed})
  end

  test "an answer is read once with result/2" do
    assert Transport.outcome({:ok, %Finch.Response{status: 204, body: ""}}) == {204, {:ok, %{}}}
  end
end
